//! 🕷️ Original graph properties and recursive values share one typed relationship workspace.
use super::{SemioGraphSnapshot,SemioGraphNode,SemioGraphEdge,SemioGraphPort,SemioGraphPortKind,SemioValueEntry,identity,single_float_row,float_columns,VALUES};
use crate::standards::v1::subsets::value::{schema::snapshot::SemioValue,io::sqlite::snapshot::{ValueForestStorage,reconstruct_value_forest_into}};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,artifact::{RowIndex,RowIndexStorage,reconstruct_text_into},transfer::{SchemaValidationStorage,validate_database_into,validate_component_into,reserve,heap_sort}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
#[derive(semio_framework_value::RetireOwned)]
struct Prefix{snapshot:Option<SemioGraphSnapshot>,validation:SchemaValidationStorage,indexes:[RowIndexStorage;6],orders:[Vec<usize>;6],names:[Vec<usize>;2],roots:Vec<i64>,root_indices:Vec<(i64,usize)>,forest:ValueForestStorage}
fn empty()->Prefix{Prefix{snapshot:Some(super::native_decoding::empty()),validation:SchemaValidationStorage::empty(),indexes:std::array::from_fn(|_|RowIndexStorage::empty()),orders:std::array::from_fn(|_|Vec::new()),names:std::array::from_fn(|_|Vec::new()),roots:Vec::new(),root_indices:Vec::new(),forest:ValueForestStorage::empty()}}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn properties(output:&mut Vec<SemioValueEntry>,rows:&RowIndex<'_>,order:&[usize],parent:i64,indices:&[(i64,usize)],forest:&mut ValueForestStorage,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let range=rows.range_by(order,(0,Some(parent)),control,|row|Ok((0,Some(row.integer(1)?))))?;*output=reserve(range.len(),control)?;for position in range{let row=rows.row(order[position])?;output.push(SemioValueEntry{key:String::new(),value:SemioValue::Null});let entry=output.last_mut().unwrap();reconstruct_text_into(&mut entry.key,control,row.text(3)?)?;let id=row.integer(4)?;let index=indices.binary_search_by_key(&id,|entry|entry.0).map_err(|_|invalid("missing admitted Semio graph property root"))?;entry.value=forest.take_root(indices[index].1)?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,order.len())?;}Ok(())}
fn optional(output:&mut Option<String>,text:Option<&str>,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{if let Some(text)=text{*output=Some(String::new());reconstruct_text_into(output.as_mut().unwrap(),control,text)?;}Ok(())}
pub(super)fn reconstruct(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,declared:&str)->Result<SemioGraphSnapshot,ValueError>{crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding::workspace::reconstruct_projected(control,empty,|prefix,control|{
 let phase=SqliteSnapshotPhase::ReconstructSnapshot;control.check_database(database,phase)?;validate_database_into(&mut prefix.validation,database,declared,phase,control)?;validate_component_into(&mut prefix.validation,database,SemioGraphSnapshot::SQLITE_SCHEMA,phase,control)?;let document=single_float_row(database,"semio_graph_document")?;identity(document,2)?;if document.rowid!=1{return Err(invalid("invalid Semio graph document identifier"))}let [node_index,edge_index,port_index,node_property_index,port_property_index,edge_property_index]=&mut prefix.indexes;let [node_order,edge_order,port_order,node_property_order,port_property_order,edge_property_order]=&mut prefix.orders;let [node_names,edge_names]=&mut prefix.names;
 let nodes=RowIndex::new(node_index,database,"semio_graph_node",10,float_columns("semio_graph_node"),control,"invalid Semio graph node identity")?;let edges=RowIndex::new(edge_index,database,"semio_graph_edge",10,float_columns("semio_graph_edge"),control,"invalid Semio graph edge identity")?;let ports=RowIndex::new(port_index,database,"semio_graph_port",6,&[],control,"invalid Semio graph port identity")?;let node_properties=RowIndex::new(node_property_index,database,"semio_graph_property",5,&[],control,"invalid Semio graph property identity")?;let port_properties=RowIndex::new(port_property_index,database,"semio_graph_port_property",5,&[],control,"invalid Semio graph port property identity")?;let edge_properties=RowIndex::new(edge_property_index,database,"semio_graph_edge_property",5,&[],control,"invalid Semio graph edge property identity")?;nodes.ordered_into(node_order,2,control,"Semio graph node ordinals must be contiguous")?;edges.ordered_into(edge_order,2,control,"Semio graph edge ordinals must be contiguous")?;nodes.unique_text(node_names,nodes.indices(),3,control,"duplicate Semio graph node identity")?;edges.unique_text(edge_names,edges.indices(),3,control,"duplicate Semio graph edge identity")?;
 for source in [&nodes,&edges]{for(count,&index)in source.indices().iter().enumerate(){if source.row(index)?.integer(1)?!=1{return Err(invalid("invalid Semio graph document owner"))}control.checkpoint(phase,count+1,source.len())?;}}for(count,&index)in ports.indices().iter().enumerate(){if nodes.get(ports.row(index)?.integer(1)?,control)?.is_none(){return Err(invalid("dangling Semio graph port owner"))}control.checkpoint(phase,count+1,ports.len())?;}for(count,&index)in edges.indices().iter().enumerate(){let row=edges.row(index)?;if nodes.get(row.integer(4)?,control)?.is_none()||nodes.get(row.integer(5)?,control)?.is_none(){return Err(invalid("dangling Semio graph node"))}control.checkpoint(phase,count+1,edges.len())?;}
 let roots_count=node_properties.len().checked_add(port_properties.len()).and_then(|v|v.checked_add(edge_properties.len())).ok_or_else(||invalid("Semio graph property count overflow"))?;prefix.roots=reserve(roots_count,control)?;prefix.root_indices=reserve(roots_count,control)?;for(rows,owner)in [(&node_properties,&nodes),(&port_properties,&ports),(&edge_properties,&edges)]{for &index in rows.indices(){let row=rows.row(index)?;if owner.get(row.integer(1)?,control)?.is_none(){return Err(invalid("dangling Semio graph property owner"))}let root=row.integer(4)?;prefix.root_indices.push((root,prefix.roots.len()));prefix.roots.push(root);control.checkpoint(phase,prefix.roots.len(),roots_count)?;}}heap_sort(&mut prefix.root_indices,phase,control,|a,b,_|Ok(a.0.cmp(&b.0)))?;if prefix.root_indices.windows(2).any(|pair|pair[0].0==pair[1].0){return Err(invalid("multiply owned Semio graph property value"))}
 for(rows,order)in [(&ports,&mut *port_order),(&node_properties,&mut *node_property_order),(&port_properties,&mut *port_property_order),(&edge_properties,&mut *edge_property_order)]{rows.grouped_by_into(order,2,control,"Semio graph relationship ordinals must be contiguous",|row|Ok((0,Some(row.integer(1)?))))?;}reconstruct_value_forest_into(&mut prefix.forest,database,VALUES,&prefix.roots,None,control)?;let snapshot=prefix.snapshot.as_mut().unwrap();snapshot.nodes=reserve(node_order.len(),control)?;snapshot.edges=reserve(edge_order.len(),control)?;
 for(ordinal,&index)in node_order.iter().enumerate(){let row=nodes.row(index)?;snapshot.nodes.push(SemioGraphNode::default());let node=snapshot.nodes.last_mut().unwrap();let range=ports.range_by(port_order,(0,Some(row.rowid)),control,|row|Ok((0,Some(row.integer(1)?))))?;node.ports=reserve(range.len(),control)?;for position in range{let row=ports.row(port_order[position])?;let kind=match row.text(4)?{"in"=>SemioGraphPortKind::In,"out"=>SemioGraphPortKind::Out,"in_out"=>SemioGraphPortKind::InOut,_=>return Err(invalid("unknown Semio graph port kind"))};node.ports.push(SemioGraphPort{kind,..Default::default()});let port=node.ports.last_mut().unwrap();reconstruct_text_into(&mut port.name,control,row.text(3)?)?;reconstruct_text_into(&mut port.category,control,row.text(5)?)?;properties(&mut port.properties,&port_properties,port_property_order,row.rowid,&prefix.root_indices,&mut prefix.forest,control)?;control.checkpoint(phase,ordinal,node.ports.len())?;}reconstruct_text_into(&mut node.id.value,control,row.text(3)?)?;reconstruct_text_into(&mut node.kind,control,row.text(4)?)?;reconstruct_text_into(&mut node.label,control,row.text(5)?)?;node.position.x=row.real(6)?;node.position.y=row.real(7)?;node.width=row.real(8)?;node.height=row.real(9)?;properties(&mut node.properties,&node_properties,node_property_order,row.rowid,&prefix.root_indices,&mut prefix.forest,control)?;control.checkpoint(phase,ordinal+1,node_order.len())?;}
 for(ordinal,&index)in edge_order.iter().enumerate(){let row=edges.row(index)?;let from=nodes.get(row.integer(4)?,control)?.ok_or_else(||invalid("dangling Semio graph source node"))?;let to=nodes.get(row.integer(5)?,control)?.ok_or_else(||invalid("dangling Semio graph target node"))?;snapshot.edges.push(SemioGraphEdge::default());let edge=snapshot.edges.last_mut().unwrap();reconstruct_text_into(&mut edge.id.value,control,row.text(3)?)?;reconstruct_text_into(&mut edge.source.value,control,from.text(3)?)?;reconstruct_text_into(&mut edge.target.value,control,to.text(3)?)?;reconstruct_text_into(&mut edge.kind,control,row.text(6)?)?;reconstruct_text_into(&mut edge.label,control,row.text(7)?)?;optional(&mut edge.source_port,row.optional_text(8)?,control)?;optional(&mut edge.target_port,row.optional_text(9)?,control)?;properties(&mut edge.properties,&edge_properties,edge_property_order,row.rowid,&prefix.root_indices,&mut prefix.forest,control)?;control.checkpoint(phase,ordinal+1,edge_order.len())?;}if !prefix.forest.roots_consumed(){return Err(invalid("unconsumed Semio graph property value"))}reconstruct_text_into(&mut snapshot.schema,control,document.text(1)?)?;control.checkpoint(phase,roots_count,roots_count)
},|prefix|prefix.snapshot.take().unwrap())}
